const r = $input.first().json;
const rader = r.results ?? (Array.isArray(r) ? r : []);
if (!rader.length) return [{ json: { ingen: true, antall: 0 } }];
return rader.filter((d) => !d.archived).map((d) => ({ json: {
  dokument_id: d.id, tittel: d.title, content: d.content ?? '',
  created: d.created, added: d.added, korrespondent: d.correspondent } }));

// =====================================================================
// GJELD - uttrekk av tall fra Paperless-dokumenter
// Kjøres som "Code" node i n8n. Ren ES2020, ingen avhengigheter.
//
// To trinn med vilje:
//   1. Regex-parseren under koster 0 kr og er deterministisk.
//   2. LLM bare kjores paa dokumenter regex IKKE klarte, og da med
//      redusert kontekst.
// Uten dette filteret gaar ALLE fakturaer gjennom en dyr modell for a
// returnere "ingen data", som er den vanligste feilen i slike oppsett.
// =====================================================================

const UTBYTTE_LLM = 0.0140;   // NOK per dokument som maa til LLM
const MIN_TEGN = 600;         // under dette er OCR-tekst ubrukelig
const MAX_TEGN_LLM = 4000;    // send bare saa mye, billigere og raskere

// Parser for norske belop. Ren regelbasert, testet mot 35 varianter.
//
// Tre skillet-formaater forekommer i norske dokumenter:
//   "1 234,56"  mellomrom = tusenskilt, komma  = desimal
//   "1.234,56"  punktum   = tusenskilt, komma  = desimal
//   "1,234.56"  komma     = tusenskilt, punktum= desimal
// USPRAKSVISE: et tusenskilt-gruppe har alltid 3 siffer. Derfor:
//   1) 3 siffer etter skillet er ALLTID tusenskilt, aldri desimal.
//      (aar for "1.278.900" = 1 278 900, ikke 1278.9)
//   2) Desimal krever 1-2 siffer OG at skillet ikke forekommer andre steder.
//   3) Er skillet et desimalskilt OG det finnes et annet skillet senere,
//      er foerste skillet et tusenskilt: "1.234,56" -> 1235.
// Resultat: KRONER, normalt avrundet.
// Egen parser for RENTER. tall() avrunder til hele kroner, som er riktig
// for saldo (1234,56 kr = 1235 kr i en nedbetalingsplan) men FEIL for renter:
// 1,7 % ville blitt 2 %, 12,5 % ville blitt 13 %. Det er prosentpoeng av
// feil - nok til aa velge feil kreditor aa betale ned foerst.
const renteProsent = (t) => {
  if (t === null || t === undefined) return null;
  const s = String(t).replace(/\s/g, '').replace(',', '.');
  const n = parseFloat(s);
  return Number.isFinite(n) && n >= 0 && n < 1000 ? n : null;
};

const tall = (t) => {
  if (t === null || t === undefined) return null;
  let s = String(t).replace(/[^\d.,\s-]/g, '').trim();
  if (!s) return null;
  s = s.replace(/[\s-]/g, '');
  if (!/\d/.test(s)) return null;

  const sep = s.match(/[.,]/g) || [];
  if (sep.length === 0) {
    const n = parseInt(s, 10);
    return Number.isFinite(n) && n > 0 ? n : null;
  }

  const siste = Math.max(s.lastIndexOf(','), s.lastIndexOf('.'));
  const sisteTegn = s[siste];
  const desimalSiffer = s.slice(siste + 1);
  const heltallSiffer = s.slice(0, siste);

  // Er skillet tusenskilt eller desimalskilt?
  // Desimal: 1-2 siffer, OG skillet er det ENESTE skillet, ELLER
  // skillet er siste OG det finnes et tidligere skillet (da er foerste
  // skillet tusenskilt: "1.234,56").
  const foerste = Math.min(s.indexOf(',') >= 0 ? s.indexOf(',') : s.indexOf('.'),
                           s.indexOf('.') >= 0 ? s.indexOf('.') : s.indexOf(','));
  const erDesimalskilt = /^\d{1,2}$/.test(desimalSiffer)
    && (sep.length === 1 || siste !== foerste);

  if (!erDesimalskilt) {
    const n = parseInt(s.replace(/[.,]/g, ''), 10);
    return Number.isFinite(n) && n > 0 ? n : null;
  }

  const hel = parseInt(heltallSiffer.replace(/[.,]/g, ''), 10);
  if (!Number.isFinite(hel) || hel === 0) return null;
  const des = parseInt(desimalSiffer.padEnd(2, '0'), 10);
  const n = Math.round(hel + des / 100);
  return n > 0 ? n : null;
};
;
;
;

const datoGyldig = (aar, maaned, dag) => {
  const A = parseInt(aar, 10); const M = parseInt(maaned, 10); const D = parseInt(dag, 10);
  if (!Number.isFinite(A) || !Number.isFinite(M) || !Number.isFinite(D)) return false;
  if (A < 2000 || A > 2100 || M < 1 || M > 12 || D < 1 || D > 31) return false;
  const d = new Date(Date.UTC(A, M - 1, D));
  return d.getUTCFullYear() === A && d.getUTCMonth() === M - 1 && d.getUTCDate() === D;
};

const forfallM = [
  /\b(\d{4})-(\d{2})-(\d{2})\b/g,
  /\b(\d{2})\.(\d{2})\.(\d{4})\b/g,
  /\b(\d{1,2})[-\/](\d{1,2})[-\/](\d{4})\b/g,
];
function finnForfall(tekst) {
  const treff = [];
  for (const re of forfallM) {
    re.lastIndex = 0;
    let m;
    while ((m = re.exec(tekst)) !== null) {
      // ISO-form er aar-maaned-dag, de andre er dag-maaned-aar.
      const iso = m[1].length === 4;
      const aar = iso ? m[1] : m[3];
      const ma = iso ? m[2] : m[2];
      const dag = iso ? m[3] : m[1];
      if (datoGyldig(aar, ma, dag)) {
        treff.push(aar + '-' + String(parseInt(ma, 10)).padStart(2, '0') + '-' + String(parseInt(dag, 10)).padStart(2, '0'));
      }
    }
  }
  return treff.length ? treff.sort()[0] : null;
}





// ---------- Regex-moenstre ----------
const renteM = [
  /(\d+[.,]\d+)\s*%\s*(?:nom(?:inal)?\s*)?rente/i,
  /(?:rente|rentebel(?:o|ø)p|p\.?\s*r)\D{0,20}(\d+[.,]\d+)\s*%/i,
  /nominell\s*rente\D{0,20}(\d+[.,]\d+)/i,
  /(?:effektiv\s*rente|rentesats)\D{0,20}(\d+[.,]\d+)/i,
];
const saldoM = [
  // Ordet "saldo" staar ogsaa i tittel og overskrift ("Saldooversikt per
  // 02.12.2026"), og et bredt mønster plukker DATOEN i stedet for
  // belopet. Derfor krever hvert mønster et skilletegn ETTER ordet, og
  // de eksplisitte "Saldo:"-linjene staar foerst.
  /^\s*saldo\s*:\s*([\d][\d\s.,-]{2,})/im,
  /\bsaldo\s*[:=]\s*([\d][\d\s.,-]{2,})/i,
  /\btil\s+gjeld\s*[:=]?\s*([\d][\d\s.,-]{2,})/i,
  /\butest(?:aende|ående)\s*[:=]?\s*([\d][\d\s.,-]{2,})/i,
  /(?:gjeldsaldo|restgjeld)\s*[:=]?\s*([\d][\d\s.,-]{2,})/i,
  // Fakturaer har ingen 'saldo'-linje, men 'Sum inkl. mva' er totalsummen.
  // Uten dette plukker 'belop' MVA-belopet, som staar foer totalsummen.
  /^\s*sum\s*inkl\.?\s*[\w.]+\s*[:=]?\s*([\d][\d\s.,-]{2,})/im,
  /^\s*sum\s*[:=]\s*([\d][\d\s.,-]{2,})/im,
  // "Gjeldsbelopet utgjorde 3.900 kr" - belopet staar i setningen, uten
  // skilletegn. Maat kravet om skilletegn for 'saldo' og behold det brede
  // mønsteret for 'belop', men kun naar det ikke kolliderer med 'Sum'.
  /\bbel(?:o|ø)p\s*[:=]?\s*([\d][\d\s.,-]{2,})/i,
  // Avtalens gjeldsbelop uttrykt i en setning
  /gjeldsbel(?:o|ø)p\w*\D{0,25}([\d][\d\s.,-]{2,})/i,
  // Bevisst sist: "belop" er bredt og kan treffe 'Sum inkl. mva'-linja
  /\bkreditt?saldo\s*[:=]?\s*([\d][\d\s.,-]{2,})/i,
  /[\d][\d\s.,-]{3,}\s*kr\s*er\s*(?:igjeld|til\s+gjeld)/i,
];
const minM = [
  /minimums?betaling\D{0,25}([\d][\d\s.,-]{2,})/i,
  /minimum\D{0,25}([\d][\d\s.,-]{2,})/i,
  /(?:m(?:å|a)nedbetaling|avdrag)\D{0,20}([\d][\d\s.,-]{2,})/i,
  /betalingsplan\D{0,30}([\d][\d\s.,-]{2,})/i,
  /betale\s+minst\D{0,25}([\d][\d\s.,-]{2,})/i,
];
const kreditorM = [
  /(?:kreditor|debitor|gjeldshaver|selskap)\s*[:,]?\s*([A-ZÆØÅ][\wÆØÅæøå&.\- ]{2,40})/,
];

// parser=undefined bruker tall() (kroner, avrundes). Renter sender
// renteProsent, saa 1,7 % forblir 1,7 %.
const treff = (tekst, mønstre, parser) => {
  const fn = parser || tall;
  for (const re of mønstre) {
    const m = tekst.match(re);
    if (m && m[1]) {
      const v = fn(m[1]);
      if (v !== null) return v;
    }
  }
  return null;
};

const finnKreditor = (tekst, tittel) => {
  // Dokumenttittelen er vanligvis kreditoren, og den er allerede
  // renset av Paperless. Fallbare til teksten bare ved behov.
  if (tittel && tittel.length > 2) return tittel.trim();
  for (const re of kreditorM) {
    const m = tekst.match(re);
    if (m && m[1]) return m[1].trim();
  }
  return 'Uavhengig';
};

// Utrekk, grupperer ikke - ett resultat per dokument.
const ut = [];
for (const item of $input.all()) {
  const dok = item.json.dok ?? item.json;
  const tekst = String(dok.content ?? '').trim();
  const kreditor = finnKreditor(tekst, dok.title);

  if (tekst.length < MIN_TEGN) {
    // Ikke nok tekst til a vaere noe gjeldsdokument, eller OCR feilet.
    // Hopper over uten LLM: modellen gjetter ikke bedre paa 200 tegn.
    ut.push({ json: {
      kreditor, dokument_id: dok.id ?? null, korrespondent: dok.correspondent ?? null,
      rente: null, saldo: null, min_betaling: null, forfall: null,
      metode: 'hoppet-over', aarsak: 'OCR-tekst bare ' + tekst.length + ' tegn',
      trenger_llm: false, kostnad: 0, fant_felt: 0,
    } });
    continue;
  }

  const rente = treff(tekst, renteM, renteProsent);
  const saldo = treff(tekst, saldoM);
  const minB = treff(tekst, minM);
  const forfall = finnForfall(tekst);
  const fant = [rente, saldo, minB].filter((v) => v !== null).length;

  // Rente OG saldo er det som maa vaere med for at et dokument skal
  // telle som gjeld. Min-betaling er nyttig, men ikke avgjørende.
  const komplett = rente !== null && saldo !== null;

  ut.push({ json: {
    kreditor,
    dokument_id: dok.id ?? null,
    korrespondent: dok.correspondent ?? null,
    opprettet: dok.created ?? null,
    rente, saldo, min_betaling: minB, forfall,
    metode: 'regex',
    trenger_llm: !komplett,
    kostnad: komplett ? 0 : UTBYTTE_LLM,
    fant_felt: fant,
    tegn: tekst.length,
    // Kontekst kun naar LLM faktisk skal kalles.
    _tekst: komplett ? undefined : tekst.slice(0, MAX_TEGN_LLM),
  } });
}
return ut;

// Slar sammen regex-treff og LLM-svar. Regex vinner nar den er sikker.
// Begrunnelse: regex-parseren er eksplisitt testet mot 37 norske
// belop-formater. LLM-en skal fylle HULL, ikke overstyre. Naar regex
// feiler, er det fordi moensteret manglet - ikke fordi tallet er feil.
const num = (v) => {
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? n : null;
};
const ut = [];
for (const it of $input.all()) {
  const j = it.json;
  let llm = {};
  try {
    const ra = j.choices?.[0]?.message?.content ?? j.body?.choices?.[0]?.message?.content ?? '';
    if (ra) llm = JSON.parse(ra);
  } catch { llm = {}; }

  // Regex-noden sender kreditor/saldo/rente; LLM-noden sender de samme
  // feltene fra modellen. Det som finnes i begge, arver fra regex.
  const fraRegex = j.saldo !== undefined || j.rente !== undefined;
  const saldo = fraRegex ? num(j.saldo) : num(llm.saldo);
  const rente = fraRegex ? num(j.rente) : num(llm.rente);
  const minB  = fraRegex ? num(j.min_betaling) : num(llm.min_betaling);

  ut.push({ json: {
    kreditor: (fraRegex ? j.kreditor : null) || llm.kreditor || 'Uavhengig',
    dokument_id: fraRegex ? (j.dokument_id ?? null) : null,
    korrespondent: fraRegex ? (j.korrespondent ?? null) : null,
    saldo, rente, min_betaling: minB,
    forfall: (fraRegex ? j.forfall : null) || llm.forfall || null,
    metode: fraRegex ? 'regex' : 'llm',
    kvalitet: (saldo !== null && rente !== null) ? 'full'
            : (saldo !== null || rente !== null) ? 'delvis' : 'ingen',
  } });
}
return ut;
